   246	int sc_connect_card(sc_reader_t *reader, sc_card_t **card_out)
   247	{
   248	        sc_card_t *card;
   249	        sc_context_t *ctx;
   250	        struct sc_card_driver *driver;
   251	        int i, r = 0, idx, connected = 0;
   252	
   253	        if (card_out == NULL || reader == NULL)
   254	                return SC_ERROR_INVALID_ARGUMENTS;
   255	        ctx = reader->ctx;
   256	        SC_FUNC_CALLED(ctx, SC_LOG_DEBUG_VERBOSE);
   257	        if (reader->ops->connect == NULL)
   258	                LOG_FUNC_RETURN(ctx, SC_ERROR_NOT_SUPPORTED);
   259	
   260	        card = sc_card_new(ctx);
   261	        if (card == NULL)
   262	                LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
   263	        r = reader->ops->connect(reader);
   264	        if (r)
   265	                goto err;
   266	
   267	        connected = 1;
   268	        card->reader = reader;
   269	        card->ctx = ctx;
   270	
   271	        if (reader->flags & SC_READER_ENABLE_ESCAPE)
   272	                sc_detect_escape_cmds(reader);
   273	
   274	        memcpy(&card->atr, &reader->atr, sizeof(card->atr));
   275	        memcpy(&card->uid, &reader->uid, sizeof(card->uid));
   276	
   277	        _sc_parse_atr(reader);
   278	
   279	        /* See if the ATR matches any ATR specified in the config file */
   280	        if ((driver = ctx->forced_driver) == NULL) {
   281	                sc_log(ctx, "matching configured ATRs");
   282	                for (i = 0; ctx->card_drivers[i] != NULL; i++) {
   283	                        driver = ctx->card_drivers[i];
   284	
   285	                        if (driver->atr_map == NULL ||
   286	                            !strcmp(driver->short_name, "default")) {
   287	                                driver = NULL;
   288	                                continue;
   289	                        }
   290	                        sc_log(ctx, "trying driver '%s'", driver->short_name);
   291	                        idx = _sc_match_atr(card, driver->atr_map, NULL);
   292	                        if (idx >= 0) {
   293	                                struct sc_atr_table *src = &driver->atr_map[idx];
   294	
   295	                                sc_log(ctx, "matched driver '%s'", driver->name);
   296	                                /* It's up to card driver to notice these correctly */
   297	                                card->name = src->name;
   298	                                card->type = src->type;
   299	                                card->flags = src->flags;
   300	                                break;
   301	                        }
   302	                        driver = NULL;
   303	                }
   304	        }
   305	
   306	        if (driver != NULL) {
   307	                /* Forced driver, or matched via ATR mapping from config file */
   308	                card->driver = driver;
   309	
   310	                memcpy(card->ops, card->driver->ops, sizeof(struct sc_card_operations));
   311	                if (card->ops->match_card != NULL)
   312	                        if (card->ops->match_card(card) != 1)
   313	                                sc_log(ctx, "driver '%s' match_card() failed: %s (will continue anyway)", card->driver->name, sc_strerror(r));
   314	
   315	                if (card->ops->init != NULL) {
   316	                        r = card->ops->init(card);
   317	                        if (r) {
   318	                                sc_log(ctx, "driver '%s' init() failed: %s", card->driver->name, sc_strerror(r));
   319	                                goto err;
   320	                        }
   321	                }
   322	        }
   323	        else {
   324	                sc_card_t uninitialized = *card;
   325	                sc_log(ctx, "matching built-in ATRs");
   326	                for (i = 0; ctx->card_drivers[i] != NULL; i++) {
   327	                        /* FIXME If we had a clean API description, we'd propably get a
   328	                         * cleaner implementation of the driver's match_card and init,
   329	                         * which should normally *not* modify the card object if
   330	                         * unsuccessful. However, after years of relentless hacking, reality
   331	                         * is different: The card object is changed in virtually every card
   332	                         * driver so in order to prevent unwanted interaction, we reset the
   333	                         * card object here and hope that the card driver at least doesn't
   334	                         * allocate any internal ressources that need to be freed. If we
   335	                         * had more time, we should refactor the existing code to not
   336	                         * modify sc_card_t until complete success (possibly by combining
   337	                         * `match_card()` and `init()`) */
   338	                        *card = uninitialized;
   339	
   340	                        struct sc_card_driver *drv = ctx->card_drivers[i];
   341	                        const struct sc_card_operations *ops = drv->ops;
   342	
   343	                        sc_log(ctx, "trying driver '%s'", drv->short_name);
   344	                        if (ops == NULL || ops->match_card == NULL)   {
   345	                                continue;
   346	                        }
   347	                        else if (!(ctx->flags & SC_CTX_FLAG_ENABLE_DEFAULT_DRIVER)
   348	                                        && !strcmp("default", drv->short_name))   {
   349	                                sc_log(ctx , "ignore 'default' card driver");
   350	                                continue;
   351	                        }
   352	
   353	                        /* Needed if match_card() needs to talk with the card (e.g. card-muscle) */
   354	                        *card->ops = *ops;
   355	                        if (ops->match_card(card) != 1)
   356	                                continue;
   357	                        sc_log(ctx, "matched: %s", drv->name);
   358	                        memcpy(card->ops, ops, sizeof(struct sc_card_operations));
   359	                        card->driver = drv;
   360	                        r = ops->init(card);
   361	                        if (r) {
   362	                                sc_log(ctx, "driver '%s' init() failed: %s", drv->name, sc_strerror(r));
   363	                                if (r == SC_ERROR_INVALID_CARD) {
   364	                                        card->driver = NULL;
   365	                                        continue;
   366	                                }
   367	                                goto err;
   368	                        }
   369	                        break;
   370	                }
   371	        }
   372	        if (card->driver == NULL) {
   373	                sc_log(ctx, "unable to find driver for inserted card");
   374	                r = SC_ERROR_INVALID_CARD;
   375	                goto err;
   376	        }
   377	        if (card->name == NULL)
   378	                card->name = card->driver->name;
   379	
   380	        /* initialize max_send_size/max_recv_size to a meaningful value */
   381	        card->max_recv_size = sc_get_max_recv_size(card);
   382	        card->max_send_size = sc_get_max_send_size(card);
   383	
   384	        sc_log(ctx,
   385	               "card info name:'%s', type:%i, flags:0x%lX, max_send/recv_size:%"SC_FORMAT_LEN_SIZE_T"u/%"SC_FORMAT_LEN_SIZE_T"u",
   386	               card->name, card->type, card->flags, card->max_send_size,
   387	               card->max_recv_size);
   388	
   389	#ifdef ENABLE_SM
   390	        /* Check, if secure messaging module present. */
   391	        r = sc_card_sm_check(card);
   392	        if (r)   {
   393	                sc_log(ctx, "cannot load secure messaging module");
   394	                goto err;
   395	        }
   396	#endif
   397	        *card_out = card;
   398	
   399	        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
   400	err:
   401	        if (connected)
   402	                reader->ops->disconnect(reader);
   403	        if (card != NULL)
   404	                sc_card_free(card);
   405	        LOG_FUNC_RETURN(ctx, r);
   406	}
